@page "/dashboard"
@using sv_4a4854a7de064cd9a4480550ac170ee2.Services
@inject WarehouseState Warehouse
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard - @Warehouse.SelectedWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-4" style="max-width: 500px;">
    <div class="card-body">
        <h5 class="card-title">@Warehouse.SelectedWarehouseName</h5>
        <p class="card-text">
            Low-stock alerts:
            <span class="badge bg-danger fs-6">@AlertService.LowStockCount</span>
        </p>
        <p class="text-muted small mb-0">
            Polling every 10 seconds. Last updated: @_lastUpdated.ToString("HH:mm:ss")
        </p>
    </div>
</div>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;
    private DateTime _lastUpdated = DateTime.Now;

    protected override void OnInitialized()
    {
        _alertHandler = () => InvokeAsync(() =>
        {
            _lastUpdated = DateTime.Now;
            StateHasChanged();
        });

        _warehouseHandler = () => InvokeAsync(StateHasChanged);

        AlertService.OnAlertCountChanged += _alertHandler;
        Warehouse.OnChange += _warehouseHandler;

        AlertService.StartPolling();
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= _alertHandler;
        Warehouse.OnChange -= _warehouseHandler;
        AlertService.StopPolling();
    }
}

